module benchmark/solution

import std/json (decode, encode, Json, JArray, JBool, JNull, JNumber, JObject, JString, jint, js)
import std/list (map)
import std/string (join)
import std/math (floatToInt, intToFloat)

pure func setField(fields: [{key: string, value: Json}], k: string, v: Json) -> [{key: string, value: Json}] =
  match fields {
    [] => [{key: k, value: v}],
    f :: rest => if f.key == k then {key: k, value: v} :: rest else f :: setField(rest, k, v)
  }

pure func update(j: Json, k: string, v: Json) -> Json =
  match j {
    JObject(fields) => JObject(setField(fields, k, v)),
    other => other
  }

pure func render(j: Json) -> string =
  match j {
    JObject(fields) => "{${join(", ", map(\f. "${encode(JString(f.key))}: ${render(f.value)}", fields))}}",
    JArray(items) => "[${join(", ", map(\x. render(x), items))}]",
    JNumber(n) => if intToFloat(floatToInt(n)) == n then show(floatToInt(n)) else show(n),
    other => encode(other)
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(obj) => {
      let updated = update(update(obj, "age", jint(31)), "role", js("senior engineer"));
      println(render(updated))
    },
    Err(e) => println(e)
  }
}

