    JObject(fields) => "{${join(", ", map(\f. "${encode(JString(f.key))}: ${render(f.value)}", fields))}}",
    JArray(items) => "[${join(", ", map(\x. render(x), items))}]",
    JNumber(n) => if intToFloat(floatToInt(n)) == n then show(floatToInt(n)) else show(n),
    other => encode(other)
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(obj) => {
      let updated = update(update(obj, "age", jint(31)), "role", js("senior engineer"));
      println(render(updated))
    },
    Err(e) => println(e)
  }
}
